describe('Modal Dialog Responsiveness on Mobile Screens', () => {
  beforeEach(() => {
    cy.visit('/modal-page');
  });

  it('should display modal correctly and be responsive on mobile screen sizes', () => {
    // Intercept modal open API call
    cy.intercept('GET', '/api/modal/open').as('openModal');

    // Click button to open modal
    cy.get('[data-testid="open-modal-btn"]').click();

    // Wait for modal to open
    cy.wait('@openModal');

    // Verify modal is visible
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Verify modal content is visible
    cy.get('[data-testid="modal-title"]').should('contain', 'Modal Title');
    cy.get('[data-testid="modal-body"]').should('be.visible');

    // Verify modal is not overflowing horizontally
    cy.get('[data-testid="modal-dialog"]').should('have.css', 'overflow-x', 'hidden');

    // Verify modal is centered on screen
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Verify modal has correct width on mobile
    cy.get('[data-testid="modal-dialog"]').should('have.css', 'max-width', '100%');

    // Verify modal is scrollable if content exceeds viewport height
    cy.get('[data-testid="modal-body"]').should('be.visible');
    cy.get('[data-testid="modal-body"]').should('have.css', 'overflow-y', 'auto');

    // Verify close button is visible and functional
    cy.get('[data-testid="close-modal-btn"]').should('be.visible');
    cy.get('[data-testid="close-modal-btn"]').click();

    // Verify modal is closed
    cy.get('[data-testid="modal-dialog"]').should('not.exist');
  });

  it('should handle modal responsiveness when screen size changes', () => {
    // Open modal
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.wait('@openModal');

    // Verify modal is visible on desktop size
    cy.get('[data-testid="modal-dialog"]').should('be.visible');
    cy.get('[data-testid="modal-dialog"]').should('have.css', 'max-width', '500px');

    // Change viewport to mobile size
    cy.viewport('iphone-x');

    // Verify modal is still visible and responsive
    cy.get('[data-testid="modal-dialog"]').should('be.visible');
    cy.get('[data-testid="modal-dialog"]').should('have.css', 'max-width', '100%');

    // Verify modal content is still readable on mobile
    cy.get('[data-testid="modal-title"]').should('be.visible');
    cy.get('[data-testid="modal-body"]').should('be.visible');

    // Verify modal is not causing horizontal scroll on mobile
    cy.get('[data-testid="modal-dialog"]').should('not.have.css', 'overflow-x', 'scroll');

    // Verify modal can be closed from mobile view
    cy.get('[data-testid="close-modal-btn"]').click();
    cy.get('[data-testid="modal-dialog"]').should('not.exist');

    // Change viewport back to desktop size
    cy.viewport('desktop');

    // Verify modal can be reopened and is responsive on desktop
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.wait('@openModal');
    cy.get('[data-testid="modal-dialog"]').should('be.visible');
    cy.get('[data-testid="modal-dialog"]').should('have.css', 'max-width', '500px');
  });
});
